create or replace function public.srk_worker_cancel_booking(p_booking_worker_id uuid, p_reason text)
returns public.srk_booking_workers
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_booking public.service_bookings%rowtype;
 v_worker public.srk_worker_profiles%rowtype;
 v_customer_user_id uuid;
 v_remaining integer;
 v_requested integer;
 v_daily_count integer;
 v_request public.srk_worker_cancellation_approval_requests%rowtype;
 v_case public.srk_support_cases%rowtype;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_booking_worker_id is null or length(btrim(coalesce(p_reason,'')))<5 then
   raise exception 'Assignment and cancellation reason are required' using errcode='22023';
 end if;
 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_booking_worker_id and wp.user_id=auth.uid()
 for update of bw;
 if not found then raise exception 'Booking assignment not found for this worker' using errcode='42501'; end if;
 if v_assignment.assignment_status not in ('offered','accepted','assigned') then
   raise exception 'This assignment cannot be cancelled directly; contact Support'; end if;
 select * into v_booking from public.service_bookings where id=v_assignment.booking_id for update;
 if not found then raise exception 'Booking not found'; end if;
 select * into v_worker from public.srk_worker_profiles where id=v_assignment.worker_id;
 if exists(select 1 from public.srk_worker_work_sessions s where s.booking_worker_id=v_assignment.id
   and (s.billable_seconds>0 or s.session_status in ('running','paused','completed'))) then
   raise exception 'Work has started or timer evidence exists; contact Support for review'; end if;

 select * into v_request from public.srk_worker_cancellation_approval_requests
 where booking_worker_id=v_assignment.id for update;
 if found and v_request.request_status='pending' then
   update public.srk_booking_workers set cancellation_request_status='pending',updated_at=clock_timestamp()
   where id=v_assignment.id returning * into v_assignment;
   return v_assignment;
 elsif found and v_request.request_status='rejected' then
   raise exception 'Admin rejected this cancellation request. Contact Support for help';
 elsif found and v_request.request_status='cancelled' then
   raise exception 'This cancellation request is no longer active';
 end if;

 if not (found and v_request.request_status='approved') then
   select count(*) into v_daily_count
   from public.srk_booking_cancellation_events e
   where e.actor_user_id=auth.uid()
     and (e.cancelled_at at time zone 'Asia/Kolkata')::date=(clock_timestamp() at time zone 'Asia/Kolkata')::date;
   if v_daily_count>=2 then
     insert into public.srk_support_cases(booking_id,raised_by,raised_by_role,category,subject,description,priority)
     values(v_booking.id,auth.uid(),v_assignment.worker_role,'worker_cancellation_approval',
       'Approval required for third daily cancellation',
       'Worker requested cancellation after reaching the daily limit of two. Reason: '||btrim(p_reason),
       'high') returning * into v_case;
     insert into public.srk_support_case_events(case_id,actor_user_id,action,new_status,note)
     values(v_case.id,auth.uid(),'worker_cancellation_approval_requested','open',p_reason);
     insert into public.srk_worker_cancellation_approval_requests(
       booking_worker_id,booking_id,worker_id,worker_user_id,worker_role,cancellation_reason,support_case_id
     ) values(v_assignment.id,v_booking.id,v_assignment.worker_id,auth.uid(),v_assignment.worker_role,p_reason,v_case.id)
     returning * into v_request;
     update public.srk_booking_workers set cancellation_request_status='pending',updated_at=clock_timestamp()
     where id=v_assignment.id returning * into v_assignment;
     insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
     select au.user_id,'worker_cancellation_approval','Worker cancellation approval required',
       'A '||v_assignment.worker_role||' has requested a third cancellation today. Please review support case '||coalesce(v_case.case_number,v_case.id::text)||'.',
       v_booking.id from public.srk_admin_users au;
     return v_assignment;
   end if;
 end if;

 update public.srk_booking_workers
 set assignment_status='cancelled',released_at=clock_timestamp(),
     cancellation_request_status=case when v_request.request_status='approved' then 'approved' else null end,
     admin_note='Worker cancellation: '||btrim(p_reason),updated_at=clock_timestamp()
 where id=v_assignment.id returning * into v_assignment;
 update public.srk_worker_schedule_blocks set block_status='cancelled',updated_at=clock_timestamp()
 where booking_worker_id=v_assignment.id and block_status in ('reserved','confirmed','in_progress');

 select count(*) into v_remaining from public.srk_booking_workers
 where booking_id=v_booking.id and worker_role=v_assignment.worker_role
   and assignment_status in ('accepted','assigned','working','paused','completed');
 v_requested:=case when v_assignment.worker_role='technician'
   then v_booking.requested_technician_count else v_booking.requested_helper_count end;
 update public.srk_booking_no_show_reports set status='cancelled',resolved_at=clock_timestamp(),
   resolution_note='Worker assignment cancelled during no-show wait'
 where booking_worker_id=p_booking_worker_id and status='waiting';
 if v_remaining<v_requested then
   update public.srk_booking_matching_queue set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
   where booking_id=v_booking.id and queue_status<>'cancelled';
   if v_assignment.worker_role='technician' and v_remaining=0 and v_booking.status in ('confirmed','assigned') then
     update public.service_bookings set status='new' where id=v_booking.id;
   end if;
 end if;
 insert into public.srk_booking_cancellation_events(booking_id,actor_user_id,actor_role,reason)
 values(v_booking.id,auth.uid(),v_assignment.worker_role,p_reason);
 if v_request.request_status='approved' then
   update public.srk_worker_cancellation_approval_requests set completed_at=clock_timestamp()
   where id=v_request.id;
 end if;
 select customer_user_id into v_customer_user_id from public.service_bookings where id=v_booking.id;
 if v_customer_user_id is not null then
   insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
   values(v_customer_user_id,'worker_assignment_cancelled','Worker assignment cancelled',
     'A '||v_assignment.worker_role||' cancelled their assignment. SRK ELECTRONIC is searching for a replacement. Reason: '||btrim(p_reason),
     v_booking.id,'/bookings/'||v_booking.id::text);
 end if;
 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
 select au.user_id,'worker_assignment_cancelled','Worker cancelled an assignment',
   'Worker '||v_worker.worker_code||' cancelled booking '||coalesce(v_booking.order_number,v_booking.id::text)||'. Reason: '||btrim(p_reason),
   v_booking.id,'/admin/bookings/'||v_booking.id::text from public.srk_admin_users au;
 return v_assignment;
end
$function$;

create or replace function public.srk_admin_review_worker_cancellation(p_request_id uuid,p_decision text,p_note text default null)
returns public.srk_worker_cancellation_approval_requests
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare v public.srk_worker_cancellation_approval_requests%rowtype; v_old text;
begin
 if not public.srk_has_admin_permission('support.manage') then raise exception 'Support permission required'; end if;
 if p_decision not in ('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;
 select * into v from public.srk_worker_cancellation_approval_requests where id=p_request_id for update;
 if not found then raise exception 'Cancellation request not found'; end if;
 if v.request_status<>'pending' then raise exception 'Request is not pending'; end if;
 update public.srk_worker_cancellation_approval_requests
 set request_status=p_decision,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),admin_note=p_note
 where id=p_request_id returning * into v;
 update public.srk_booking_workers set cancellation_request_status=p_decision,updated_at=clock_timestamp()
 where id=v.booking_worker_id;
 update public.srk_support_cases set status=case when p_decision='approved' then 'resolved' else 'closed' end,
   resolution=case when p_decision='approved' then 'Approved. Worker must confirm cancellation by retrying the request.'
     else 'Rejected. '||coalesce(p_note,'') end,
   resolved_at=clock_timestamp(),updated_at=clock_timestamp(),admin_note=p_note
 where id=v.support_case_id;
 insert into public.srk_support_case_events(case_id,actor_user_id,action,old_status,new_status,note)
 select v.support_case_id,auth.uid(),'worker_cancellation_'||p_decision,'open',
   case when p_decision='approved' then 'resolved' else 'closed' end,p_note;
 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
 values(v.worker_user_id,'worker_cancellation_'||p_decision,
   case when p_decision='approved' then 'Cancellation approved' else 'Cancellation request rejected' end,
   case when p_decision='approved' then 'Admin approved your cancellation. Please reopen the booking and confirm cancellation.'
     else 'Admin rejected your cancellation request. Please contact Support.' end,v.booking_id);
 return v;
end
$function$;

revoke all on function public.srk_admin_review_worker_cancellation(uuid,text,text) from public,anon;
grant execute on function public.srk_admin_review_worker_cancellation(uuid,text,text) to authenticated;

create or replace function public.srk_customer_cancel_booking_v2(p_booking_id uuid,p_reason text)
returns public.service_bookings
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v public.service_bookings%rowtype;
 v_fee_amount numeric(12,2):=0;
 v_fee_basis text;
 v_free_minutes integer;
 v_on_way_fee numeric(12,2);
 v_arrived_fee numeric(12,2);
 v_accepted_at timestamptz;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if length(coalesce(p_reason,''))<5 then raise exception 'Cancellation reason is required'; end if;
 select * into v from public.service_bookings where id=p_booking_id and customer_user_id=auth.uid() for update;
 if not found then raise exception 'Customer booking not found'; end if;
 v_free_minutes:=coalesce((v.operational_settings_snapshot->>'cancellation_free_window_minutes')::integer,
   (select (setting_value #>> '{}')::integer from public.srk_system_settings where setting_key='cancellation_free_window_minutes'),5);
 v_on_way_fee:=coalesce((v.operational_settings_snapshot->>'cancellation_technician_on_way_fee')::numeric,
   (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='cancellation_technician_on_way_fee'),49);
 v_arrived_fee:=coalesce((v.operational_settings_snapshot->>'cancellation_technician_arrived_fee')::numeric,
   (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='cancellation_technician_arrived_fee'),99);
 if v.status not in ('new','confirmed','assigned') then
   raise exception 'Booking can no longer be cancelled directly; contact Support so timer evidence is preserved';
 end if;
 if exists(select 1 from public.srk_worker_work_sessions s join public.srk_booking_workers bw on bw.id=s.booking_worker_id
   where bw.booking_id=p_booking_id and (s.billable_seconds>0 or s.session_status in ('running','paused'))) then
   raise exception 'Work has started or billable time exists; contact Support for review';
 end if;

 select min(bw.accepted_at) into v_accepted_at
 from public.srk_booking_workers bw
 where bw.booking_id=p_booking_id and bw.worker_role='technician' and bw.accepted_at is not null;

 if v_accepted_at is not null and clock_timestamp()>v_accepted_at+make_interval(mins=>v_free_minutes) then
   if exists(select 1 from public.srk_booking_workers bw where bw.booking_id=p_booking_id and bw.worker_role='technician' and bw.arrived_at is not null) then
     v_fee_amount:=v_arrived_fee; v_fee_basis:='technician_arrived';
   elsif exists(select 1 from public.srk_booking_workers bw where bw.booking_id=p_booking_id and bw.worker_role='technician' and bw.on_the_way_at is not null) then
     v_fee_amount:=v_on_way_fee; v_fee_basis:='technician_on_the_way';
   end if;
 end if;

 update public.service_bookings set status='cancelled',admin_change_reason='Customer cancellation: '||p_reason
 where id=p_booking_id returning * into v;
 update public.srk_booking_matching_queue set queue_status='cancelled',updated_at=clock_timestamp()
 where booking_id=p_booking_id;
 update public.srk_booking_no_show_reports set status='cancelled',resolved_at=clock_timestamp(),
   resolution_note='Booking cancelled by customer during no-show wait'
 where booking_id=p_booking_id and status='waiting';
 update public.srk_worker_work_sessions set session_status='cancelled',ended_at=clock_timestamp(),updated_at=clock_timestamp()
 where booking_worker_id in(select id from public.srk_booking_workers where booking_id=p_booking_id)
   and session_status='not_started';
 update public.srk_booking_workers set assignment_status='cancelled',admin_note='Customer cancellation: '||p_reason,updated_at=clock_timestamp()
 where booking_id=p_booking_id and assignment_status in ('offered','accepted','assigned');
 update public.srk_worker_schedule_blocks set block_status='cancelled',updated_at=clock_timestamp()
 where booking_worker_id in(select id from public.srk_booking_workers where booking_id=p_booking_id)
   and block_status in ('reserved','confirmed','in_progress');
 update public.srk_booking_location_shares set ended_at=clock_timestamp()
 where booking_id=p_booking_id and ended_at is null;

 insert into public.srk_booking_cancellation_events(booking_id,actor_user_id,actor_role,reason)
 values(p_booking_id,auth.uid(),'customer',p_reason);

 if v_fee_amount>0 then
   insert into public.srk_booking_cancellation_fees(cancelled_booking_id,customer_user_id,fee_amount,fee_basis,status)
   values(p_booking_id,auth.uid(),v_fee_amount,v_fee_basis,'pending')
   on conflict(cancelled_booking_id) do nothing;
 end if;

 update public.srk_booking_cancellation_fees
 set status='pending',next_booking_id=null,added_to_next_booking_at=null
 where next_booking_id=p_booking_id and status='added_to_next_booking';
 update public.service_bookings set pending_cancellation_fee_amount=0 where id=p_booking_id;

 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
 select w.user_id,'booking_cancelled','Booking cancelled','Customer cancelled the booking. Reason: '||p_reason,p_booking_id
 from public.srk_booking_workers bw join public.srk_worker_profiles w on w.id=bw.worker_id
 where bw.booking_id=p_booking_id;
 return v;
end
$function$;

