 end if;
 update public.srk_booking_workers set assignment_status='cancelled',released_at=clock_timestamp(),
   cancellation_request_status=case when v_request.request_status='approved' then 'approved' else null end,
   admin_note='Worker cancellation: '||btrim(p_reason),updated_at=clock_timestamp()
 where id=v_assignment.id returning * into v_assignment;
 update public.srk_worker_schedule_blocks set block_status='cancelled',updated_at=clock_timestamp()
 where booking_worker_id=v_assignment.id and block_status in ('reserved','confirmed','in_progress');
 select count(*) into v_remaining from public.srk_booking_workers
 where booking_id=v_booking.id and worker_role=v_assignment.worker_role
   and assignment_status in ('accepted','assigned','working','paused','completed');
 v_requested:=case when v_assignment.worker_role='technician' then v_booking.requested_technician_count
   else v_booking.requested_helper_count end;
 update public.srk_booking_no_show_reports set status='cancelled',resolved_at=clock_timestamp(),
   resolution_note='Worker assignment cancelled during no-show wait'
 where booking_worker_id=p_booking_worker_id and status='waiting';
 if v_remaining<v_requested then
   update public.srk_booking_matching_queue set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
   where booking_id=v_booking.id and queue_status<>'cancelled';
   if v_assignment.worker_role='technician' and v_remaining=0 and v_booking.status in ('confirmed','assigned') then
     update public.service_bookings set status='new' where id=v_booking.id; end if;
 end if;
 insert into public.srk_booking_cancellation_events(booking_id,actor_user_id,actor_role,reason)
 values(v_booking.id,auth.uid(),v_assignment.worker_role,p_reason);
 if v_request.request_status='approved' then
   update public.srk_worker_cancellation_approval_requests set completed_at=clock_timestamp() where id=v_request.id; end if;
 select customer_user_id into v_customer_user_id from public.service_bookings where id=v_booking.id;
 if v_customer_user_id is not null then
   insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
   values(v_customer_user_id,'worker_assignment_cancelled','Worker assignment cancelled',
     'A '||v_assignment.worker_role||' cancelled their assignment. SRK ELECTRONIC is searching for a replacement. Reason: '||btrim(p_reason),
     v_booking.id,'/bookings/'||v_booking.id::text); end if;
 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
 select au.user_id,'worker_assignment_cancelled','Worker cancelled an assignment',
   'Worker '||v_worker.worker_code||' cancelled booking '||coalesce(v_booking.order_number,v_booking.id::text)||
   '. Reason: '||btrim(p_reason),v_booking.id,'/admin/bookings/'||v_booking.id::text from public.srk_admin_users au;
 return v_assignment;
end
$function$;

create index if not exists srk_worker_cancel_approval_booking_fk_idx
  on public.srk_worker_cancellation_approval_requests (booking_id);
create index if not exists srk_worker_cancel_approval_support_case_fk_idx
  on public.srk_worker_cancellation_approval_requests (support_case_id);
create index if not exists srk_worker_cancel_approval_worker_fk_idx
  on public.srk_worker_cancellation_approval_requests (worker_id);

CREATE OR REPLACE FUNCTION public.srk_find_eligible_workers(p_booking_id uuid, p_worker_type text)
RETURNS TABLE(worker_id uuid, worker_code text, worker_type text, distance_km numeric)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_booking public.service_bookings%rowtype;
  v_search_radius numeric;
  v_attempts integer;
  v_initial_radius numeric;
  v_expansion_step numeric;
  v_max_radius numeric;
begin
  if p_worker_type not in ('technician','helper') then
    raise exception 'Invalid worker type';
  end if;
  select * into v_booking from public.service_bookings where id=p_booking_id;
  if not found then raise exception 'Booking not found'; end if;

  select coalesce(q.attempts,0) into v_attempts
  from public.srk_booking_matching_queue q where q.booking_id=p_booking_id;

  select
    coalesce((v_booking.operational_settings_snapshot->>'initial_matching_radius_km')::numeric,
      (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='initial_matching_radius_km'),30),
    coalesce((v_booking.operational_settings_snapshot->>'matching_radius_expansion_step_km')::numeric,
      (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='matching_radius_expansion_step_km'),30),
    coalesce((v_booking.operational_settings_snapshot->>'maximum_matching_radius_km')::numeric,
      (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='maximum_matching_radius_km'),200)
  into v_initial_radius,v_expansion_step,v_max_radius;

  v_search_radius:=least(v_max_radius,v_initial_radius+coalesce(v_attempts,0)*v_expansion_step);

  return query
  select w.id,w.worker_code,w.worker_type,
    case when v_booking.booking_latitude is null then null::numeric else
      round((6371*acos(least(1,greatest(-1,
        cos(radians(v_booking.booking_latitude))*cos(radians(w.location_lat))*cos(radians(w.location_lng)-radians(v_booking.booking_longitude))+
        sin(radians(v_booking.booking_latitude))*sin(radians(w.location_lat))
      ))))::numeric,2)
    end
  from public.srk_worker_profiles w
  where w.worker_type=p_worker_type
    and w.category_id=v_booking.category_id
    and w.verification_status='approved' and w.is_active and w.is_online
    and (v_booking.booking_latitude is null or (w.location_lat is not null and w.location_lng is not null))
    and exists(
      select 1 from public.srk_worker_skills ws
      where ws.worker_id=w.id and ws.skill_id=v_booking.selected_skill_id
        and ws.verification_status='approved'
        and (coalesce(v_booking.higher_skill_consent_level_id,v_booking.requested_skill_level_id) is null
          or ws.skill_level_id=coalesce(v_booking.higher_skill_consent_level_id,v_booking.requested_skill_level_id))
    )
    and (
      (v_booking.booking_latitude is not null and
        (6371*acos(least(1,greatest(-1,
          cos(radians(v_booking.booking_latitude))*cos(radians(w.location_lat))*cos(radians(w.location_lng)-radians(v_booking.booking_longitude))+
          sin(radians(v_booking.booking_latitude))*sin(radians(w.location_lat))
        ))))<=least(v_search_radius,w.service_radius_km))
      or (v_booking.booking_latitude is null and
        (w.pincode=v_booking.pincode or
          (lower(trim(w.state))=lower(trim(v_booking.state)) and lower(trim(w.district))=lower(trim(v_booking.district)))))
    )
    and not exists(
      select 1 from public.srk_worker_work_sessions s
      where s.worker_id=w.id and s.session_status in ('running','paused')
    )
    and not exists(
      select 1 from public.srk_booking_workers bw
      where bw.worker_id=w.id and bw.assignment_status in ('working','paused')
    )
    -- Do not send new offers to a worker who has an accepted assignment
    -- that has not yet been given a customer-confirmed schedule.
    and not exists(
      select 1 from public.srk_booking_workers bw
      where bw.worker_id=w.id
        and bw.assignment_status in ('accepted','assigned')
        and not exists(
          select 1 from public.srk_worker_schedule_blocks sb
          where sb.booking_worker_id=bw.id
            and sb.block_status in ('reserved','confirmed','in_progress')
        )
    )
    and not exists(
      select 1 from public.srk_worker_schedule_blocks sb
      where sb.worker_id=w.id and sb.block_status in ('reserved','confirmed','in_progress')
        and sb.starts_at<=clock_timestamp()+make_interval(hours=>coalesce(v_booking.requested_duration_hours,1))
        and sb.ends_at>clock_timestamp()
    )
  order by
    case when v_booking.booking_latitude is null and w.pincode=v_booking.pincode then 0 else 1 end,
    4 nulls last,w.created_at;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_respond_assignment(p_assignment_id uuid, p_accept boolean)
RETURNS public.srk_booking_workers
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
declare
  v_assignment public.srk_booking_workers%rowtype;
  v_worker public.srk_worker_profiles%rowtype;
  v_booking public.service_bookings%rowtype;
  v_accepted_count integer;
  v_requested_count integer;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select bw.* into v_assignment
  from public.srk_booking_workers bw
  join public.srk_worker_profiles wp on wp.id=bw.worker_id
  where bw.id=p_assignment_id and wp.user_id=auth.uid()
  for update of bw;

  if not found or v_assignment.assignment_status<>'offered' then
    raise exception 'Offer not found or no longer pending';
  end if;

  if p_accept and v_assignment.offer_expires_at is not null
     and v_assignment.offer_expires_at<=clock_timestamp() then
    raise exception 'Offer has expired; wait for the next eligible assignment';
  end if;

  select * into v_booking from public.service_bookings
  where id=v_assignment.booking_id for update;
  if not found or v_booking.status='cancelled' then
    raise exception 'Booking is no longer available';
  end if;

  select * into v_worker from public.srk_worker_profiles
  where id=v_assignment.worker_id for update;
  if not found then raise exception 'Worker profile not found'; end if;

  if p_accept then
    if v_worker.verification_status<>'approved' or not v_worker.is_active then
      raise exception 'Worker is not currently approved and active';
    end if;

    perform pg_advisory_xact_lock(hashtextextended(v_worker.id::text,0));

    if exists(
      select 1 from public.srk_worker_work_sessions s
      where s.worker_id=v_worker.id and s.session_status in ('running','paused')
    ) or exists(
      select 1 from public.srk_booking_workers bw
      where bw.worker_id=v_worker.id and bw.assignment_status in ('working','paused')
    ) then
      raise exception 'Finish or complete the active/paused booking before accepting another booking';
    end if;

    -- An accepted assignment without a confirmed schedule is treated as
    -- occupying the worker's next available slot. This prevents two immediate
    -- bookings from being accepted before either has a schedule reservation.
    if exists(
      select 1 from public.srk_booking_workers bw
      where bw.worker_id=v_worker.id
        and bw.id<>v_assignment.id
        and bw.assignment_status in ('accepted','assigned')
        and not exists(
          select 1 from public.srk_worker_schedule_blocks sb
          where sb.booking_worker_id=bw.id
            and sb.block_status in ('reserved','confirmed','in_progress')
        )
    ) then
      raise exception 'Another accepted booking still needs a customer-confirmed schedule';
    end if;

    v_requested_count:=case when v_assignment.worker_role='technician'
      then v_booking.requested_technician_count else v_booking.requested_helper_count end;

    select count(*) into v_accepted_count
    from public.srk_booking_workers
    where booking_id=v_assignment.booking_id
      and worker_role=v_assignment.worker_role
      and assignment_status in ('accepted','assigned','working','paused','completed');

    if v_accepted_count>=v_requested_count then
      raise exception 'Requested number of this worker role has already been filled';
    end if;
  end if;

  update public.srk_booking_workers
  set assignment_status=case when p_accept then 'accepted' else 'rejected' end,
      accepted_at=case when p_accept then clock_timestamp() else null end,
      rejected_at=case when p_accept then null else clock_timestamp() end,
      offer_expires_at=null,updated_at=clock_timestamp()
  where id=p_assignment_id returning * into v_assignment;

  if p_accept and v_assignment.worker_role='technician' then
    update public.service_bookings set status='confirmed'
    where id=v_assignment.booking_id and status='new';
  end if;

  update public.srk_booking_matching_queue
  set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
  where booking_id=v_assignment.booking_id and queue_status not in ('fulfilled','cancelled');

  return v_assignment;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_session_action(
 p_session_id uuid,p_action text,p_pause_reason text DEFAULT NULL::text,
 p_note text DEFAULT NULL::text,p_idempotency_key text DEFAULT NULL::text
) RETURNS public.srk_worker_work_sessions
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_existing_event public.srk_worker_session_events%rowtype;
 v_user_id uuid; v_booking_id uuid; v_now timestamptz:=clock_timestamp();
 v_elapsed bigint; v_booking public.service_bookings%rowtype; v_expected_event_type text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_idempotency_key is not null and
   (length(btrim(p_idempotency_key))=0 or length(p_idempotency_key)>200) then
   raise exception 'Invalid idempotency key' using errcode='22023';
 end if;
 select * into v_session from public.srk_worker_work_sessions where id=p_session_id for update;
 if not found then raise exception 'Work session not found'; end if;
 select wp.user_id,bw.booking_id into v_user_id,v_booking_id
 from public.srk_booking_workers bw join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=v_session.booking_worker_id;
 select * into v_booking from public.service_bookings where id=v_booking_id;
 if v_user_id is distinct from auth.uid() and not coalesce(public.is_srk_admin(),false) then
  raise exception 'Not authorized for this work session';
 end if;

 if p_idempotency_key is not null then
  v_expected_event_type:=case p_action when 'start' then 'started' when 'pause' then 'paused'
   when 'resume' then 'resumed' when 'complete' then 'completed' else null end;
  select * into v_existing_event from public.srk_worker_session_events
  where idempotency_key=p_idempotency_key for share;
  if found then
   if v_existing_event.session_id is distinct from p_session_id
    or v_existing_event.event_type is distinct from v_expected_event_type
    or v_existing_event.actor_user_id is distinct from auth.uid()
    or v_existing_event.pause_reason is distinct from p_pause_reason
    or v_existing_event.note is distinct from p_note
    or v_existing_event.source is distinct from 'app' then
    raise exception 'Idempotency key was already used for a different timer event' using errcode='22023';
   end if;
   return v_session;
  end if;
 end if;

 if p_action='start' then
  if v_session.session_status<>'not_started' then raise exception 'Session cannot be started from current state'; end if;
  update public.srk_worker_work_sessions set session_status='running',started_at=v_now,last_resumed_at=v_now,updated_at=v_now,
   start_latitude=(select location_lat from public.srk_worker_profiles where id=v_session.worker_id),
   start_longitude=(select location_lng from public.srk_worker_profiles where id=v_session.worker_id),
   last_gps_latitude=(select location_lat from public.srk_worker_profiles where id=v_session.worker_id),
   last_gps_longitude=(select location_lng from public.srk_worker_profiles where id=v_session.worker_id)
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
   where id=v_session.booking_worker_id and assignment_status in ('accepted','assigned','paused');
  update public.service_bookings set status='in_progress',work_started_at=coalesce(work_started_at,v_now)
   where id=v_booking_id and status in ('new','confirmed','assigned','in_progress');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'started',v_now,auth.uid(),p_note,p_idempotency_key);

 elsif p_action='pause' then
  if v_session.session_status<>'running' then raise exception 'Only a running session can be paused'; end if;
  if p_pause_reason not in ('lunch','market_other') then raise exception 'Pause must be Lunch or Market/Other Task'; end if;
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions set session_status='paused',pause_started_at=v_now,
   pause_minimum_until=v_now+make_interval(mins=>case when p_pause_reason='lunch'
    then coalesce((v_booking.operational_settings_snapshot->>'lunch_pause_minimum_minutes')::integer,60)
    else coalesce((v_booking.operational_settings_snapshot->>'other_pause_minimum_minutes')::integer,120) end),
   billable_seconds=least(5184000,billable_seconds+v_elapsed),last_resumed_at=null,
   pause_reason=p_pause_reason,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now where id=v_session.booking_worker_id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,idempotency_key)
   values(p_session_id,'paused',v_now,auth.uid(),p_pause_reason,p_note,p_idempotency_key);

 elsif p_action='resume' then
  if v_session.session_status<>'paused' then raise exception 'Only a paused session can be resumed'; end if;
  if v_session.pause_minimum_until is not null and v_now<v_session.pause_minimum_until then
   raise exception 'Minimum pause duration has not elapsed';
  end if;
  update public.srk_worker_work_sessions set session_status='running',last_resumed_at=v_now,pause_reason=null,
   pause_started_at=null,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now where id=v_session.booking_worker_id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'resumed',v_now,auth.uid(),p_note,p_idempotency_key);

 elsif p_action='complete' then
  if v_session.session_status not in ('running','paused') then raise exception 'Session cannot be completed from current state'; end if;
  v_elapsed:=case when v_session.session_status='running'
   then greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint) else 0 end;
  update public.srk_worker_work_sessions set session_status='completed',
   billable_seconds=least(5184000,billable_seconds+v_elapsed),ended_at=v_now,last_resumed_at=null,
   completion_note=p_note,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='assigned',updated_at=v_now
   where id=v_session.booking_worker_id and assignment_status in ('working','paused');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'completed',v_now,auth.uid(),p_note,p_idempotency_key);
 else
  raise exception 'Unsupported session action';
 end if;
 return v_session;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_customer_respond_schedule_proposal(
 p_proposal_id uuid,p_accept boolean,p_note text DEFAULT NULL::text
)
RETURNS public.srk_booking_schedule_proposals
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_proposal public.srk_booking_schedule_proposals%rowtype;
 v_assignment public.srk_booking_workers%rowtype;
 v_booking public.service_bookings%rowtype;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_proposal_id is null or (p_note is not null and length(p_note)>1000) then
  raise exception 'Valid schedule proposal response is required' using errcode='22023';
 end if;

 -- Lock in booking -> assignment -> proposal order, matching cancellation paths.
 select bw.booking_id into v_assignment.booking_id
 from public.srk_booking_schedule_proposals p
 join public.srk_booking_workers bw on bw.id=p.booking_worker_id
 join public.service_bookings b on b.id=bw.booking_id
 where p.id=p_proposal_id and b.customer_user_id=auth.uid();
 if not found then raise exception 'Proposal not found for this customer'; end if;

 select * into v_booking from public.service_bookings
 where id=v_assignment.booking_id and customer_user_id=auth.uid()
 for update;
 if not found then raise exception 'Customer booking not found'; end if;

 select * into v_assignment from public.srk_booking_workers
 where id=(select booking_worker_id from public.srk_booking_schedule_proposals where id=p_proposal_id)
 for update;
 if not found then raise exception 'Booking assignment not found'; end if;

 select * into v_proposal from public.srk_booking_schedule_proposals
 where id=p_proposal_id for update;
 if not found or v_proposal.status<>'proposed' then
  raise exception 'Proposal not found or no longer pending';
 end if;

 if v_booking.status='cancelled'
    or v_assignment.assignment_status not in ('accepted','assigned','working','paused') then
  update public.srk_booking_schedule_proposals
  set status='cancelled',
      customer_response_note=coalesce(nullif(btrim(p_note),''),'Automatically cancelled because the booking assignment is no longer active.'),
      responded_at=clock_timestamp()
  where id=p_proposal_id returning * into v_proposal;
  insert into public.srk_booking_schedule_events(proposal_id,actor_user_id,action,note)
  values(p_proposal_id,auth.uid(),'cancelled','Booking or worker assignment is no longer active.');
  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
  select w.user_id,'schedule_response','Schedule proposal cancelled',
    'The proposed schedule is no longer available because the booking assignment is no longer active.',
    v_booking.id
  from public.srk_worker_profiles w where w.id=v_assignment.worker_id;
  return v_proposal;
 end if;

 if v_proposal.proposed_start_at<=clock_timestamp() then
  update public.srk_booking_schedule_proposals
  set status='expired',
      customer_response_note=coalesce(nullif(btrim(p_note),''),'Proposal expired before the customer response.'),
      responded_at=clock_timestamp()
  where id=p_proposal_id returning * into v_proposal;
  insert into public.srk_booking_schedule_events(proposal_id,actor_user_id,action,note)
  values(p_proposal_id,auth.uid(),'expired','Proposal start time passed before customer response.');
  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
  select w.user_id,'schedule_response','Schedule proposal expired',
    'The customer response arrived after the proposed start time. Please propose a new schedule.',
    v_booking.id
  from public.srk_worker_profiles w where w.id=v_assignment.worker_id;
  return v_proposal;
 end if;

 if p_accept then
  insert into public.srk_worker_schedule_blocks(worker_id,booking_worker_id,starts_at,ends_at,block_status)
  values(v_assignment.worker_id,v_assignment.id,v_proposal.proposed_start_at,v_proposal.proposed_end_at,'confirmed');
 end if;

 update public.srk_booking_schedule_proposals
 set status=case when p_accept then 'accepted' else 'declined' end,
     customer_response_note=p_note,responded_at=clock_timestamp()
 where id=p_proposal_id returning * into v_proposal;

 insert into public.srk_booking_schedule_events(proposal_id,actor_user_id,action,note)
 values(p_proposal_id,auth.uid(),case when p_accept then 'accepted' else 'declined' end,p_note);

 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
 select w.user_id,'schedule_response',
   case when p_accept then 'Schedule accepted' else 'Schedule declined' end,
   case when p_accept then 'Customer accepted the proposed work schedule.' else 'Customer declined the proposed work schedule. Please propose another time.' end,
   v_booking.id
 from public.srk_worker_profiles w where w.id=v_assignment.worker_id;
 return v_proposal;
end
$function$;

alter table public.srk_booking_schedule_events
  alter column actor_user_id drop not null;
alter table public.srk_booking_schedule_events
  add column if not exists actor_type text not null default 'user';
alter table public.srk_booking_schedule_events
  add constraint srk_booking_schedule_event_actor_type_valid
  check (actor_type in ('user','system'));

create or replace function private.srk_cleanup_worker_schedule_after_assignment_terminal()
returns trigger
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_actor uuid:=auth.uid();
 v_proposal_id uuid;
 v_note text;
begin
 if tg_op='UPDATE'
    and new.assignment_status is distinct from old.assignment_status
    and new.assignment_status in ('completed','cancelled','released','rejected') then

  v_note:='Automatically closed because worker assignment status changed to '||new.assignment_status||'.';

  update public.srk_worker_schedule_blocks
  set block_status=case when ends_at<=clock_timestamp() then 'completed' else 'cancelled' end,
      updated_at=clock_timestamp()
  where booking_worker_id=new.id
    and block_status in ('reserved','confirmed','in_progress');

  for v_proposal_id in
    update public.srk_booking_schedule_proposals
    set status='cancelled',
        customer_response_note=v_note,
        responded_at=clock_timestamp()
    where booking_worker_id=new.id
      and status in ('proposed','accepted')
    returning id
  loop
    insert into public.srk_booking_schedule_events(
      proposal_id,actor_user_id,action,note,actor_type
    ) values(
      v_proposal_id,v_actor,'cancelled',v_note,
      case when v_actor is null then 'system' else 'user' end
    );
  end loop;
 end if;
 return new;
end
$function$;

revoke all on function private.srk_cleanup_worker_schedule_after_assignment_terminal() from public,anon,authenticated;

drop trigger if exists srk_cleanup_worker_schedule_on_assignment_terminal on public.srk_booking_workers;
create trigger srk_cleanup_worker_schedule_on_assignment_terminal
after update of assignment_status on public.srk_booking_workers
for each row
execute function private.srk_cleanup_worker_schedule_after_assignment_terminal();

CREATE OR REPLACE FUNCTION public.srk_worker_session_action(
 p_session_id uuid,p_action text,p_pause_reason text DEFAULT NULL::text,
 p_note text DEFAULT NULL::text,p_idempotency_key text DEFAULT NULL::text
) RETURNS public.srk_worker_work_sessions
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_existing_event public.srk_worker_session_events%rowtype;
 v_user_id uuid; v_booking_id uuid; v_now timestamptz:=clock_timestamp();
 v_elapsed bigint; v_booking public.service_bookings%rowtype; v_expected_event_type text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_idempotency_key is not null and
   (length(btrim(p_idempotency_key))=0 or length(p_idempotency_key)>200) then
   raise exception 'Invalid idempotency key' using errcode='22023';
 end if;
 select * into v_session from public.srk_worker_work_sessions where id=p_session_id for update;
 if not found then raise exception 'Work session not found'; end if;
 select wp.user_id,bw.booking_id into v_user_id,v_booking_id
 from public.srk_booking_workers bw join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=v_session.booking_worker_id;
 select * into v_booking from public.service_bookings where id=v_booking_id;
 if v_user_id is distinct from auth.uid() and not coalesce(public.is_srk_admin(),false) then
  raise exception 'Not authorized for this work session';
 end if;
 if p_idempotency_key is not null then
  v_expected_event_type:=case p_action when 'start' then 'started' when 'pause' then 'paused'
   when 'resume' then 'resumed' when 'complete' then 'completed' else null end;
  select * into v_existing_event from public.srk_worker_session_events
  where idempotency_key=p_idempotency_key for share;
  if found then
   if v_existing_event.session_id is distinct from p_session_id
    or v_existing_event.event_type is distinct from v_expected_event_type
    or v_existing_event.actor_user_id is distinct from auth.uid()
    or v_existing_event.pause_reason is distinct from p_pause_reason
    or v_existing_event.note is distinct from p_note
    or v_existing_event.source is distinct from 'app' then
    raise exception 'Idempotency key was already used for a different timer event' using errcode='22023';
   end if;
   return v_session;
  end if;
 end if;

 if p_action='start' then
  if v_session.session_status<>'not_started' then raise exception 'Session cannot be started from current state'; end if;
  update public.srk_worker_work_sessions
  set session_status='running',started_at=v_now,last_resumed_at=v_now,updated_at=v_now,
      start_latitude=null,start_longitude=null,last_gps_latitude=null,last_gps_longitude=null
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
   where id=v_session.booking_worker_id and assignment_status in ('accepted','assigned','paused');
  update public.service_bookings set status='in_progress',work_started_at=coalesce(work_started_at,v_now)
   where id=v_booking_id and status in ('new','confirmed','assigned','in_progress');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'started',v_now,auth.uid(),p_note,p_idempotency_key);

 elsif p_action='pause' then
  if v_session.session_status<>'running' then raise exception 'Only a running session can be paused'; end if;
  if p_pause_reason not in ('lunch','market_other') then raise exception 'Pause must be Lunch or Market/Other Task'; end if;
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions set session_status='paused',pause_started_at=v_now,
   pause_minimum_until=v_now+make_interval(mins=>case when p_pause_reason='lunch'
    then coalesce((v_booking.operational_settings_snapshot->>'lunch_pause_minimum_minutes')::integer,60)
    else coalesce((v_booking.operational_settings_snapshot->>'other_pause_minimum_minutes')::integer,120) end),
   billable_seconds=least(5184000,billable_seconds+v_elapsed),last_resumed_at=null,
   pause_reason=p_pause_reason,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now where id=v_session.booking_worker_id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,pause_reason,note,idempotency_key)
   values(p_session_id,'paused',v_now,auth.uid(),p_pause_reason,p_note,p_idempotency_key);

 elsif p_action='resume' then
  if v_session.session_status<>'paused' then raise exception 'Only a paused session can be resumed'; end if;
  if v_session.pause_minimum_until is not null and v_now<v_session.pause_minimum_until then
   raise exception 'Minimum pause duration has not elapsed';
  end if;
  update public.srk_worker_work_sessions set session_status='running',last_resumed_at=v_now,pause_reason=null,
   pause_started_at=null,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now where id=v_session.booking_worker_id;
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'resumed',v_now,auth.uid(),p_note,p_idempotency_key);

 elsif p_action='complete' then
  if v_session.session_status not in ('running','paused') then raise exception 'Session cannot be completed from current state'; end if;
  v_elapsed:=case when v_session.session_status='running'
   then greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint) else 0 end;
  update public.srk_worker_work_sessions set session_status='completed',
   billable_seconds=least(5184000,billable_seconds+v_elapsed),ended_at=v_now,last_resumed_at=null,
   completion_note=p_note,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='assigned',updated_at=v_now
   where id=v_session.booking_worker_id and assignment_status in ('working','paused');
  insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,idempotency_key)
   values(p_session_id,'completed',v_now,auth.uid(),p_note,p_idempotency_key);
 else
  raise exception 'Unsupported session action';
 end if;
 return v_session;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_override_work_timer(
 p_session_id uuid,p_timer_on boolean,p_reason text
) RETURNS public.srk_worker_work_sessions
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_booking_id uuid; v_worker_id uuid; v_worker_user_id uuid; v_customer_user_id uuid;
 v_now timestamptz:=clock_timestamp(); v_elapsed bigint:=0; v_previous_status text;
begin
 if auth.uid() is null or not public.is_srk_admin() then
  raise exception 'Main Admin permission required' using errcode='42501';
 end if;
 if p_session_id is null or p_timer_on is null or length(btrim(coalesce(p_reason,'')))<10 then
  raise exception 'Session, timer action and a reason of at least 10 characters are required' using errcode='22023';
 end if;
 select * into v_session from public.srk_worker_work_sessions where id=p_session_id for update;
 if not found then raise exception 'Work session not found'; end if;
 v_previous_status:=v_session.session_status;
 select bw.booking_id,bw.worker_id,wp.user_id,b.customer_user_id
 into v_booking_id,v_worker_id,v_worker_user_id,v_customer_user_id
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 join public.service_bookings b on b.id=bw.booking_id
 where bw.id=v_session.booking_worker_id;
 if not found then raise exception 'Booking worker assignment not found'; end if;

 if p_timer_on then
  if v_session.session_status not in ('not_started','paused') then
   raise exception 'Timer is already running or session is closed';
  end if;
  update public.srk_worker_work_sessions
  set session_status='running',started_at=coalesce(started_at,v_now),last_resumed_at=v_now,
      pause_reason=null,pause_started_at=null,pause_minimum_until=null,
      start_latitude=case when started_at is null then null else start_latitude end,
      start_longitude=case when started_at is null then null else start_longitude end,
      last_gps_latitude=null,last_gps_longitude=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='working',updated_at=v_now
  where id=v_session.booking_worker_id;
  update public.service_bookings set status='in_progress',work_started_at=coalesce(work_started_at,v_now)
  where id=v_booking_id and status in ('new','confirmed','assigned','in_progress');
 else
  if v_session.session_status<>'running' then raise exception 'Only a running timer can be turned off'; end if;
  v_elapsed:=greatest(0,floor(extract(epoch from(v_now-v_session.last_resumed_at)))::bigint);
  update public.srk_worker_work_sessions
  set session_status='paused',billable_seconds=least(5184000,billable_seconds+v_elapsed),
      last_resumed_at=null,pause_reason=null,pause_started_at=v_now,pause_minimum_until=null,updated_at=v_now
  where id=p_session_id returning * into v_session;
  update public.srk_booking_workers set assignment_status='paused',updated_at=v_now
  where id=v_session.booking_worker_id;
 end if;

 insert into public.srk_worker_session_events(session_id,event_type,event_at,actor_user_id,note,source)
 values(p_session_id,'admin_adjusted',v_now,auth.uid(),
  case when p_timer_on then 'ADMIN TIMER ON: ' else 'ADMIN TIMER OFF: ' end||btrim(p_reason),'admin');
 insert into public.srk_admin_timer_override_events(
  session_id,booking_id,booking_worker_id,worker_id,admin_user_id,action,reason,previous_status,new_status
 ) values(p_session_id,v_booking_id,v_session.booking_worker_id,v_worker_id,auth.uid(),
  case when p_timer_on then 'timer_on' else 'timer_off' end,btrim(p_reason),
  v_previous_status,v_session.session_status);

 if v_customer_user_id is not null then
  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
  values(v_customer_user_id,'timer_admin_override','Work timer updated by Admin',
   case when p_timer_on then 'Admin ने कारण सहित काम का टाइमर चालू किया।' else 'Admin ने कारण सहित काम का टाइमर बंद किया।' end,
   v_booking_id,'/bookings/'||v_booking_id::text);
 end if;
 if v_worker_user_id is not null then
  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id,deep_link)
  values(v_worker_user_id,'timer_admin_override','Work timer updated by Admin',
   case when p_timer_on then 'Admin ने कारण सहित आपका काम का टाइमर चालू किया।' else 'Admin ने कारण सहित आपका काम का टाइमर बंद किया।' end,
   v_booking_id,'/worker/bookings/'||v_booking_id::text);
 end if;
 return v_session;
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_worker_record_session_location(
 p_session_id uuid,p_latitude double precision,p_longitude double precision,
 p_accuracy_m numeric DEFAULT NULL::numeric
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare
 v_session public.srk_worker_work_sessions%rowtype;
 v_distance_m numeric;
 v_auto_resume_distance numeric;
 v_booking public.service_bookings%rowtype;
 v_auto_resumed boolean:=false;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_session_id is null or p_latitude is null or p_longitude is null
  or p_latitude not between -90 and 90 or p_longitude not between -180 and 180
  or (p_accuracy_m is not null and p_accuracy_m<0) then
  raise exception 'Valid GPS coordinates are required' using errcode='22023';
 end if;
 select s.* into v_session
 from public.srk_worker_work_sessions s
 join public.srk_booking_workers bw on bw.id=s.booking_worker_id
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where s.id=p_session_id and wp.user_id=auth.uid()
 for update of s;
 if not found then raise exception 'Work session not found for this worker' using errcode='42501'; end if;
 select b.* into v_booking from public.service_bookings b
 join public.srk_booking_workers bw on bw.booking_id=b.id
 where bw.id=v_session.booking_worker_id;
 v_auto_resume_distance:=coalesce((v_booking.operational_settings_snapshot->>'pause_auto_resume_distance_meters')::numeric,
  (select (setting_value #>> '{}')::numeric from public.srk_system_settings where setting_key='pause_auto_resume_distance_meters'),100);

 update public.srk_worker_work_sessions
 set last_gps_latitude=p_latitude,last_gps_longitude=p_longitude,
     start_latitude=case when session_status='running' and start_latitude is null then p_latitude else start_latitude end,
     start_longitude=case when session_status='running' and start_longitude is null then p_longitude else start_longitude end,
     updated_at=clock_timestamp()
 where id=p_session_id;

 if v_session.session_status='paused'
    and v_session.pause_minimum_until is not null
    and clock_timestamp()>=v_session.pause_minimum_until
    and v_session.start_latitude is not null and v_session.start_longitude is not null then
  v_distance_m:=6371000*2*asin(sqrt(
   power(sin(radians(p_latitude-v_session.start_latitude)/2),2)
   +cos(radians(v_session.start_latitude))*cos(radians(p_latitude))
   *power(sin(radians(p_longitude-v_session.start_longitude)/2),2)
  ));
  if v_distance_m<=v_auto_resume_distance then
   perform public.srk_worker_session_action(p_session_id,'resume',null,
    'Automatic GPS resume after minimum pause duration',
    'gps-auto-resume:'||p_session_id::text||':'||to_char(clock_timestamp(),'YYYYMMDDHH24MI'));
   v_auto_resumed:=true;
  end if;
 end if;
 return jsonb_build_object('success',true,'auto_resumed',v_auto_resumed,'distance_from_start_m',v_distance_m);
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_submit_booking_quote(
 p_booking_id uuid,p_service_charge numeric,p_materials_amount numeric,p_quote_note text DEFAULT NULL::text
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth','pg_temp'
AS $function$
declare
 v_profile_id uuid;
 v_booking public.service_bookings%rowtype;
 v_total numeric(12,2);
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_booking_id is null or p_service_charge is null or p_service_charge<=0
    or p_service_charge>10000000 then
  raise exception 'Invalid quote amounts';
 end if;
 if coalesce(p_materials_amount,0)<>0 then
  raise exception 'Materials are outside SRK billing and must not be included in the quote';
 end if;

 select id into v_profile_id
 from public.electrician_profiles
 where (user_id=auth.uid() or auth_user_id=auth.uid())
   and verification_status='approved' and active=true
 order by created_at desc limit 1;
 if v_profile_id is null then raise exception 'Approved active electrician required'; end if;

 select * into v_booking from public.service_bookings
 where id=p_booking_id and assigned_electrician_id=v_profile_id
 for update;
 if not found then raise exception 'Assigned booking not found'; end if;
 if v_booking.status not in ('assigned','inspection','quote_rejected') then
  raise exception 'Booking is not ready for a quote';
 end if;

 v_total:=round(p_service_charge,2);
 update public.service_bookings
 set service_charge=v_total,materials_amount=0,quoted_amount=v_total,
     quote_note=left(coalesce(p_quote_note,''),1000),quote_status='pending',
     quote_submitted_at=pg_catalog.now(),quote_responded_at=null,status='awaiting_quote_approval'
 where id=p_booking_id;
 return pg_catalog.jsonb_build_object('success',true,'total',v_total,'quote_status','pending');
end
$function$;

CREATE OR REPLACE FUNCTION public.srk_admin_review_worker_cancellation(
 p_request_id uuid,p_decision text,p_note text DEFAULT NULL::text
) RETURNS public.srk_worker_cancellation_approval_requests
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'pg_catalog','public','auth'
AS $function$
declare v public.srk_worker_cancellation_approval_requests%rowtype;
begin
 if not public.srk_has_admin_permission('support.manage') then
  raise exception 'Support permission required';
 end if;
 if p_decision not in ('approved','rejected') then
  raise exception 'Decision must be approved or rejected';
 end if;
 select * into v from public.srk_worker_cancellation_approval_requests
 where id=p_request_id for update;
 if not found then raise exception 'Cancellation request not found'; end if;
 if v.request_status<>'pending' then raise exception 'Request is not pending'; end if;

 update public.srk_worker_cancellation_approval_requests
 set request_status=p_decision,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),admin_note=p_note
 where id=p_request_id returning * into v;
 update public.srk_booking_workers
 set cancellation_request_status=p_decision,updated_at=clock_timestamp()
 where id=v.booking_worker_id;
 update public.srk_support_cases
 set status=case when p_decision='approved' then 'resolved' else 'closed' end,
     resolution=case when p_decision='approved'
       then 'Approved. Worker must confirm cancellation by retrying the request.'
       else 'Rejected. '||coalesce(p_note,'') end,
     resolved_at=clock_timestamp(),updated_at=clock_timestamp(),admin_note=p_note
 where id=v.support_case_id;
 insert into public.srk_support_case_events(case_id,actor_user_id,action,old_status,new_status,note)
 select v.support_case_id,auth.uid(),'worker_cancellation_'||p_decision,'open',
   case when p_decision='approved' then 'resolved' else 'closed' end,p_note;
 insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
 values(v.worker_user_id,'worker_cancellation_'||p_decision,
   case when p_decision='approved' then 'Cancellation approved' else 'Cancellation request rejected' end,
   case when p_decision='approved'
     then 'Admin approved your cancellation. Please reopen the booking and confirm cancellation.'
     else 'Admin rejected your cancellation request. Please contact Support.' end,v.booking_id);
 return v;
end
$function$;
